import { createRequire } from "node:module";
import path from "node:path";
import process from "node:process";
import { createJiti } from "jiti";
import { lilconfig } from "lilconfig";
import { defuOverrideArray } from "@weapp-tailwindcss/shared";
//#region src/module-cache.ts
const require = createRequire(import.meta.url);
/** 配置及本地辅助模块每次重新执行，已安装依赖继续复用原生缓存。 */
function clearConfigModuleCache(filename) {
	const root = require.cache[filename] ?? require.cache[require.resolve(filename)];
	const visited = /* @__PURE__ */ new Set();
	const childrenByParent = /* @__PURE__ */ new Map();
	if (root && "evalModule" in root.require) {
		for (const module of Object.values(require.cache)) if (module?.parent?.filename) {
			const children = childrenByParent.get(module.parent.filename) ?? [];
			children.push(module);
			childrenByParent.set(module.parent.filename, children);
		}
	}
	function visit(module) {
		if (visited.has(module)) return;
		visited.add(module);
		if (module !== root) {
			let directory = path.dirname(module.filename);
			while (path.dirname(directory) !== directory) {
				if (path.basename(directory) === "node_modules") return;
				directory = path.dirname(directory);
			}
		}
		for (const child of [...module.children, ...childrenByParent.get(module.filename) ?? []]) visit(child);
		if (module.parent) module.parent.children = module.parent.children.filter((child) => child !== module);
		delete require.cache[module.filename];
	}
	if (root) visit(root);
}
//#endregion
//#region src/index.ts
async function loadConfig(options) {
	const jiti = createJiti(import.meta.url, {
		moduleCache: true,
		fsCache: true
	});
	const load = (filename, source) => {
		clearConfigModuleCache(filename);
		return jiti.evalModule(source, { filename });
	};
	const { config, cwd, moduleName } = defuOverrideArray(options, {
		cwd: process.cwd(),
		moduleName: "tailwind"
	});
	const searcher = lilconfig("tailwindcss", {
		searchPlaces: [
			`${moduleName}.config.js`,
			`${moduleName}.config.cjs`,
			`${moduleName}.config.mjs`,
			`${moduleName}.config.ts`,
			`${moduleName}.config.cts`,
			`${moduleName}.config.mts`
		],
		loaders: {
			".js": load,
			".cjs": load,
			".mjs": load,
			".ts": load,
			".cts": load,
			".mts": load
		}
	});
	if (typeof config === "string" && config) {
		const configPath = path.isAbsolute(config) ? config : path.resolve(cwd, config);
		return await searcher.load(configPath);
	} else return await searcher.search(cwd);
}
//#endregion
export { loadConfig };
